  .rank{left:4px;top:3px}
  .file{right:4px;bottom:3px}
  .under-board{
    position:absolute;
    top:582px;
    left:0;
    width:576px;
    text-align:center;
    font-size:22px;
    color:#222;
    height:28px;
    opacity:.95;
  }
  .capture-note{
    position:absolute;
    top:-35px;
    left:0;
    width:576px;
    text-align:center;
    font-family:"Times New Roman",serif;
    font-size:21px;
    color:#111;
    height:25px;
  }
  @media(max-width:1100px){
    .ad{display:none}
  }
