</head>
<body>
<div class="page">
  <header class="topbar">
    <div class="top-inner">
      <div class="left-tools">
        <span class="tiny-gem">3</span>
        <span class="horse-icon">♞</span>
        <span class="flag">🇺🇸</span>
      </div>

      <div class="players">
        <div class="player">
          <div class="player-name">ROXY<small id="whiteTime">6.9s</small></div>
          <div class="avatar">◉</div>
        </div>
        <div class="score">0&nbsp; 0</div>
        <div class="player right">
          <div class="avatar bot">♙</div>
          <div class="player-name">Julien Song<small id="blackTime">1.0s</small></div>
        </div>
      </div>

      <div class="right-tools">
        <span class="flag">🇫🇷</span>
        <span style="font-size:19px">♘</span>
        <span class="tiny-gem">133</span>
      </div>
    </div>
  </header>

  <main class="content">
    <a class="ad left btn" href="javascript:void(0)">Remove ads</a>
    <a class="ad right btn" href="javascript:void(0)">Remove ads</a>

    <div class="board-wrap">
      <div id="captureNote" class="capture-note"></div>
      <div id="board" class="board"></div>
      <div id="underBoard" class="under-board"></div>
    </div>
  </main>
</div>

<script>
(() => {
  const board = document.getElementById('board');
  const underBoard = document.getElementById('underBoard');
  const captureNote = document.getElementById('captureNote');

  const symbols = {
    wK:'♔', wQ:'♕', wR:'♖', wB:'♗', wN:'♘', wP:'♙',
    bK:'♚', bQ:'♛', bR:'♜', bB:'♝', bN:'♞', bP:'♟'
  };

  // Display orientation exactly matches the screenshots:
  // white pieces at the top, black pieces at the bottom, files reversed.
  let state = [
    ['wR',null,'wB','wK','wQ','wB','wN','wR'],
    ['wP','wP','wP','wP','wP','wP','wP','wP'],
    [null,null,null,null,null,null,null,null],
    [null,null,null,null,null,null,null,null],
    [null,null,null,null,null,null,null,null],
    [null,null,null,null,null,null,null,null],
    ['bP','bP','bP','bP','bP','bP','bP','bP'],
    ['bR','bN','bB','bK','bQ','bB','bN','bR']
  ];

  let selected = null;
  let lastMove = null;
  let captured = null;
  let moveCount = 0;

  function isWhite(p){ return p && p[0] === 'w'; }
  function isBlack(p){ return p && p[0] === 'b'; }

  function render(){
    board.innerHTML = '';
    for(let r=0;r<8;r++){
      for(let c=0;c<8;c++){
        const sq = document.createElement('button');
        sq.className = 'square btn ' + (((r+c)%2===0)?'light':'dark');
        sq.dataset.r = r;
        sq.dataset.c = c;

        if(lastMove && (
          (lastMove.from.r===r && lastMove.from.c===c) ||
          (lastMove.to.r===r && lastMove.to.c===c)
        )) sq.classList.add('last');

        if(selected && selected.r===r && selected.c===c) sq.classList.add('selected');

        if(selected && !(selected.r===r && selected.c===c)){
          const target = state[r][c];
          if(!target || isWhite(target)!==isWhite(state[selected.r][selected.c])){
            if(Math.abs(selected.r-r)<=2 && Math.abs(selected.c-c)<=2)
              sq.classList.add('possible');
          }
        }

        if(c===0){
          const rank = document.createElement('span');
          rank.className='rank';
          rank.textContent = String(r+1);
          sq.appendChild(rank);
        }
        if(r===7){
          const file = document.createElement('span');
          file.className='file';
          file.textContent = 'hgfedcba'[c];
          sq.appendChild(file);
        }

        const p = state[r][c];
        if(p){
          const piece = document.createElement('span');
          piece.className = 'piece ' + (p[0]==='w'?'white':'black');
          piece.textContent = symbols[p];
          sq.appendChild(piece);
        }

        sq.addEventListener('click', handleClick);
        board.appendChild(sq);
      }
    }

    if(captured){
      captureNote.textContent = captured === 'bQ' ? '♛ +6' :
                                captured === 'bP' ? '♟♛ +7' :
                                captured === 'wP' ? '♙ +1' : '';
    } else captureNote.textContent='';

    underBoard.textContent = moveCount >= 7 ? '♙♙' : (moveCount >= 5 ? '♙ +1' : '');
  }

  function handleClick(e){
    const sq = e.currentTarget;
    const r = Number(sq.dataset.r), c = Number(sq.dataset.c);
    const p = state[r][c];

    if(!selected){
      if(p) {
        selected = {r,c};
        render();
      }
      return;
    }

    if(selected.r===r && selected.c===c){
      selected=null;
      render();
      return;
    }

    const moving = state[selected.r][selected.c];

    // Clicking another same-side piece changes selection.
    if(p && isWhite(p)===isWhite(moving)){
      selected={r,c};
      render();
      return;
    }

    captured = p || null;
    state[r][c] = moving;
    state[selected.r][selected.c] = null;
    lastMove = {from:{...selected},to:{r,c}};
    selected = null;
    moveCount++;

    // Small visual timing changes matching the progression in the screenshots.
    const wt = (6.9 + moveCount * 1.15).toFixed(1);
    const bt = (1.0 + Math.max(0,moveCount-1) * 1.35).toFixed(1);
    document.getElementById('whiteTime').textContent = wt + 's';
    document.getElementById('blackTime').textContent = bt + 's';

    render();
  }

  render();
})();
</script>
</body>
</html>
